import{_ as t,o,c as a,ag as r}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Envelope Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/allocations.md","filePath":"reference/tools/allocations.md"}'),d={name:"reference/tools/allocations.md"};function s(n,e,c,l,i,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="envelope-tools" tabindex="-1">Envelope Tools <a class="header-anchor" href="#envelope-tools" aria-label="Permalink to &quot;Envelope Tools&quot;">​</a></h1><p>All envelope tools require <strong>Manager or Owner</strong> role unless noted. The four envelope writes below (<code>allocate_hours</code>, <code>update_allocation</code>, <code>cancel_allocation</code>, <code>reactivate_allocation</code>) are performed in the web console rather than asked for in Slack; the reads on this page remain Slack-reachable. See <a href="/reference/concepts/allocations.html">Envelopes</a> for conceptual background.</p><hr><h2 id="allocate_hours" tabindex="-1">allocate_hours <a class="header-anchor" href="#allocate_hours" aria-label="Permalink to &quot;allocate_hours {#allocate_hours}&quot;">​</a></h2><p>Create a per-person hour envelope on a project.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>07. Budgets</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td></td></tr><tr><td><code>user_name</code> or <code>user_slack_id</code></td><td>✅</td><td>Person receiving the envelope</td></tr><tr><td><code>allocated_hours</code></td><td>✅</td><td>Hours for this envelope</td></tr><tr><td><code>task_id</code> or <code>task_name</code></td><td>✅</td><td>Work-category tag — must be enabled for the project</td></tr><tr><td><code>start_date</code></td><td></td><td>Envelope window start, <code>YYYY-MM-DD</code>.</td></tr><tr><td><code>end_date</code></td><td></td><td>Envelope window end, <code>YYYY-MM-DD</code>.</td></tr><tr><td><code>label</code></td><td></td><td>Free-text wayfinder (max 40 characters), e.g. &quot;Location A&quot;.</td></tr></tbody></table><p><strong>Task constraint:</strong> The task must be enabled for the target project (via <strong>Edit tasks</strong> / <code>enable_task_for_project</code>). A project with no enabled tasks cannot receive any envelope. A task that is globally active but not enabled for the project is rejected with a <code>400</code> error listing which tasks are enabled.</p><p><strong>Window (optional, storage only):</strong> <code>start_date</code>/<code>end_date</code> bound when an envelope&#39;s hours are expected to land — a bound, not a schedule. Both absent/empty (the default) means project-lifetime, exactly today&#39;s behavior. Either supplied requires both — a one-sided window is rejected (<code>❌ Failed: start_date and end_date must both be provided, or both omitted.</code>). <code>end_date</code> must be on or after <code>start_date</code> (same-day is a valid one-day window). Set only from the web console&#39;s Add-envelope form; this pair is deliberately absent from the Slack tool schema, so VERA can never set or infer one. As of this write, the window changes no calculation anywhere — proration, capacity, and availability are unaffected.</p><p><strong>Label (optional, storage only):</strong> <code>label</code> lets a manager or owner tell apart several envelopes belonging to the same person on the same project — e.g. two &quot;Photography&quot; envelopes on one project, one for Location A and one for Location B, where the task alone doesn&#39;t say what each one is for. Plain free text, trimmed, up to 40 characters (<code>❌ Failed: label must be 40 characters or fewer.</code> beyond that); blank or whitespace-only stores as no label. It is display-only — it changes no calculation anywhere. (Separately, a time entry logged from the web console <em>can</em> be attributed to one specific envelope of a same-task group — see <code>allocation_id</code> on <a href="./time.html#log_time"><code>log_time</code></a> and the bucket&#39;s per-envelope <code>hours_logged</code> above — but a label never drives that attribution on its own.) It is deliberately never shown in the Slack morning briefing. Set and shown only in the web console (Add-envelope form, the standalone envelope page, and every envelope table); this parameter is deliberately absent from the Slack tool schema, so VERA can never set, read, or mention it.</p><p><strong>Returns:</strong> envelope <code>id</code> (use for updates/cancellations), and <code>overbooked: true</code> if the person is over capacity.</p><p>If <code>overbooked: true</code> is returned, always surface the warning: &quot;⚠️ [Name] is overbooked by Xh.&quot;</p><p><strong>Both word orders accepted:</strong> <code>allocate 20h to Apex for Rachel as Design</code> (natural: <code>to &lt;project&gt; for &lt;person&gt;</code>) and <code>allocate 20h to Rachel on Apex for Design</code> (legacy: <code>to &lt;person&gt; on &lt;project&gt;</code>) resolve identically. VERA binds each name to the slot matching what it actually is — no re-asking when all slots are present.</p><hr><h2 id="update_allocation" tabindex="-1">update_allocation <a class="header-anchor" href="#update_allocation" aria-label="Permalink to &quot;update_allocation {#update_allocation}&quot;">​</a></h2><p>Change the hours or task on an existing envelope.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>07. Budgets</code> col D (hours), col I (task)</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>allocation_id</code></td><td>✅</td><td>The envelope&#39;s ID</td></tr><tr><td><code>new_allocated_hours</code></td><td></td><td>New hours value</td></tr><tr><td><code>new_task_id</code> or <code>new_task_name</code></td><td></td><td>New task category</td></tr><tr><td><code>start_date</code></td><td></td><td>New envelope window start, <code>YYYY-MM-DD</code>. Presence-based (see below).</td></tr><tr><td><code>end_date</code></td><td></td><td>New envelope window end, <code>YYYY-MM-DD</code>. Presence-based (see below).</td></tr><tr><td><code>week_hours</code></td><td></td><td>New shape: array of <code>{ week, hours }</code>. Presence-based (see below).</td></tr><tr><td><code>label</code></td><td></td><td>New free-text wayfinder (max 40 characters). Presence-based (see below).</td></tr></tbody></table><p>To find the envelope ID, call <code>get_allocations</code> or <code>get_person_allocation_summary</code> first.</p><p><strong>Restrictions:</strong> Cannot target a Retainer or Agile parent project — envelopes must reference the active period or sprint child. The error message names the active period to guide the user.</p><p><strong>Audit:</strong> The audit message shows exactly what changed (e.g. &quot;40h → 50h&quot; or &quot;task: Design → Development&quot;).</p><p><strong>Window (optional, storage only, presence-based):</strong> <code>start_date</code>/<code>end_date</code> follow the same both-or-neither and ordering rules as <code>allocate_hours</code>, but the update path is presence-based rather than value-based: omit both keys entirely to leave the existing window untouched; send both as non-empty values to set/replace it; send both as empty strings to clear it back to null; send only one (present or filled) and the call is rejected with the same <code>❌ Failed: start_date and end_date must both be provided, or both omitted.</code> message. As with <code>allocate_hours</code>, this pair is console-only and changes no calculation.</p><p><strong>Shape (optional, storage only, presence-based — issue #1810):</strong> <code>week_hours</code> is an array of <code>{ week, hours }</code> describing how an envelope&#39;s hours land across the weeks of its window — a click-to-draw bar chart in the console&#39;s Edit-envelope modal, on <code>/console/p/:projectId</code> and <code>/console/envelopes</code>. Presence-based like the window pair: the key absent leaves the existing shape untouched; <code>[]</code> or <code>null</code> clears it; a non-empty array is validated and written. Requires a window — <code>week_hours</code> is rejected with <code>❌ Failed: this envelope has no window — set a window first…</code> if <code>start_date</code>/<code>end_date</code> are both null (after this same request&#39;s own window change, if any). Every <code>week</code> must be the Monday of a week inside the window; every <code>hours</code> must be a number greater than 0 (a week with no hours is simply omitted, not stored as zero); no duplicate weeks; the sum of <code>hours</code> must not exceed the envelope&#39;s <code>allocated_hours</code> (checked server-side regardless of what the console&#39;s own client-side clamp already enforced). Stored sorted by week. <strong>This pair is console-only</strong> — absent from the Slack tool schema, same as the window — <strong>and changes no calculation.</strong> Critically: the shape is a forecast the PM owns, never an instruction handed to the person whose hours they are — no alert, chip, color, or signal anywhere may derive from comparing logged time against this shape, now or in any future issue.</p><p><strong>Deterministic routing (M-ENV-U):</strong> Natural language like &quot;update Sarah&#39;s envelope on Acme to 50h&quot; resolves the target envelope directly from the entity pipeline. If the envelope resolves unambiguously and new hours are present, VERA shows a before→after confirm gate (&quot;Change … (40h) to 50h? Reply 1 to confirm.&quot;) — no model round-trip. If the user holds two envelopes on the same project (e.g. Design + Development), VERA shows a numbered disambiguation menu; the model never picks the candidate.</p><hr><h2 id="cancel_allocation" tabindex="-1">cancel_allocation <a class="header-anchor" href="#cancel_allocation" aria-label="Permalink to &quot;cancel_allocation {#cancel_allocation}&quot;">​</a></h2><p>Mark an envelope as cancelled. The record is kept for audit purposes. Cancellation is terminal — VERA does not track lineage between a cancelled envelope and any replacement.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>07. Budgets</code> col F (status → <code>&quot;cancelled&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>allocation_id</code></p><p><strong>Deterministic routing (M-ENV-D):</strong> Natural language like &quot;cancel Sarah&#39;s envelope on Acme&quot; resolves and always shows a terminal confirm gate (&quot;Cancel … ? This is terminal — reply 1 to confirm.&quot;) before executing. Ambiguous → disambiguation menu. The model never cancels without explicit user confirmation.</p><hr><h2 id="reactivate_allocation" tabindex="-1">reactivate_allocation <a class="header-anchor" href="#reactivate_allocation" aria-label="Permalink to &quot;reactivate_allocation {#reactivate_allocation}&quot;">​</a></h2><p>Restore a cancelled envelope to active. Use when an envelope was cancelled by mistake.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>07. Budgets</code> col F (status → <code>&quot;active&quot;</code>)</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>allocation_id</code></p><p>No uniqueness check is performed — multiple active envelopes for the same user/project/task are allowed.</p><p><strong>Audit:</strong> <code>♻️</code></p><p><strong>Deterministic routing (M-ENV-D undo):</strong> Natural language like &quot;reactivate Sarah&#39;s envelope on Acme&quot; fires instantly when the cancelled envelope resolves unambiguously — no confirm gate (non-destructive). Ambiguous → disambiguation menu; the digit fires the reactivation directly. No model invocation.</p><hr><h2 id="get_allocations" tabindex="-1">get_allocations <a class="header-anchor" href="#get_allocations" aria-label="Permalink to &quot;get_allocations {#get_allocations}&quot;">​</a></h2><p>List envelopes with optional filters.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>03. Users</code>, <code>02. Projects</code>, <code>05. Tasks</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>user_id</code></td><td>Filter by person</td></tr><tr><td><code>project_id</code></td><td>Filter by project</td></tr><tr><td><code>status</code></td><td><code>&quot;active&quot;</code> (default) or <code>&quot;cancelled&quot;</code></td></tr><tr><td><code>include_usage</code></td><td><code>&quot;true&quot;</code> to add usage enrichment (see below). Default omits it.</td></tr></tbody></table><p><strong>Returns</strong>: Each allocation includes <code>user_name</code>, <code>project_name</code>, and <code>task_name</code> (the resolved task label, or <code>null</code> if no task is tagged).</p><p>When <code>include_usage=true</code>, envelopes are <strong>bucketed by <code>(user_id, project_id, task_id)</code></strong> before enrichment. Multiple envelopes sharing the same triple collapse into one bucket row; <code>allocated_hours</code> is summed and time entries are attributed once — no double-counting. Each bucket row includes:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>allocation_id</code></td><td>The single envelope&#39;s <code>id</code> if the bucket has exactly one envelope; <code>null</code> for multi-envelope buckets</td></tr><tr><td><code>envelope_ids</code></td><td>Array of all envelope IDs in this bucket</td></tr><tr><td><code>envelopes</code></td><td>Array of constituent envelope objects <code>{ allocation_id, allocated_hours, hours_logged, ... }</code> — each envelope&#39;s own <code>hours_logged</code> is the hours from entries whose <code>budget_id</code> names that exact envelope; used for per-envelope Edit/Cancel modals and, as of issue #2047, for the console&#39;s per-envelope Logged/Remaining display</td></tr><tr><td><code>display_project_id</code> / <code>display_project_name</code></td><td>The parent project for retainer/agile period children, otherwise the project itself</td></tr><tr><td><code>project_deadline</code></td><td>The period&#39;s <code>period_end</code>, or the project&#39;s <code>deadline</code>, or the parent&#39;s <code>deadline</code></td></tr><tr><td><code>hours_logged</code></td><td>Total hours attributed to this bucket (partitioned across buckets, not duplicated) — equals the sum of every constituent envelope&#39;s own <code>hours_logged</code> plus <code>hours_unattributed</code></td></tr><tr><td><code>hours_unattributed</code></td><td>Hours matching this bucket that belong to no single envelope — a time entry with no <code>budget_id</code> (e.g. logged from Slack, which never names one) or one naming an envelope outside this bucket</td></tr><tr><td><code>budget_remaining</code></td><td><code>allocated_hours − hours_logged</code> (not floored — negative values are meaningful)</td></tr><tr><td><code>pct_used</code></td><td><code>round(hours_logged / allocated_hours × 100)</code>, or <code>null</code> if <code>allocated_hours</code> is <code>0</code> and hours have been logged</td></tr><tr><td><code>project_status</code></td><td>The status (<code>active</code>, <code>cancelled</code>, <code>completed</code>, etc.) of the display project (parent for retainer/agile periods, otherwise the project itself)</td></tr></tbody></table><p>Used by the web console&#39;s top-level Envelopes overview (<code>/console/envelopes</code>) and the project detail Allocations card (<code>/console/p/:id</code>). As of issue #2047, both render each envelope&#39;s own Logged/Remaining rather than the bucket-wide figure, plus a separate row for a group&#39;s <code>hours_unattributed</code> (labelled &quot;Unattributed&quot;) when it is nonzero.</p><hr><h2 id="get_my_allocations" tabindex="-1">get_my_allocations <a class="header-anchor" href="#get_my_allocations" aria-label="Permalink to &quot;get_my_allocations {#get_my_allocations}&quot;">​</a></h2><p>The requesting user&#39;s active envelopes.</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="get_my_assignments" tabindex="-1">get_my_assignments <a class="header-anchor" href="#get_my_assignments" aria-label="Permalink to &quot;get_my_assignments {#get_my_assignments}&quot;">​</a></h2><p>&quot;What should I work on?&quot; — returns active envelopes for the requesting user with remaining hours.</p><p>This is the primary tool for Users to understand their current workload. It shows:</p><ul><li>Projects they&#39;re allocated to</li><li>Hours allocated vs. hours logged</li><li>Hours remaining in each envelope</li></ul><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><blockquote><p>Any active user. Assignment = having an active envelope. Anyone can log time to any project regardless of assignment — envelopes are a planning tool, not a gate.</p></blockquote><hr><h2 id="get_project_assignments" tabindex="-1">get_project_assignments <a class="header-anchor" href="#get_project_assignments" aria-label="Permalink to &quot;get_project_assignments {#get_project_assignments}&quot;">​</a></h2><p>Who is allocated to a project. <strong>Manager/Owner.</strong></p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>03. Users</code></p><p><strong>Returns</strong>: user_id, user_name, allocated_hours, hours_logged, hours_remaining, task_id (if tagged), status</p><p><strong>Permission</strong>: Owners see all. Managers see only their assigned projects.</p><hr><h2 id="get_person_allocation_summary" tabindex="-1">get_person_allocation_summary <a class="header-anchor" href="#get_person_allocation_summary" aria-label="Permalink to &quot;get_person_allocation_summary {#get_person_allocation_summary}&quot;">​</a></h2><p>All envelopes for one person across all their projects.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>02. Projects</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>user_name</code></p><p><strong>Returns per envelope</strong>: project_name, allocated_hours, hours_logged, hours_remaining, status, overdraw flag</p><hr><h2 id="get_project_allocation_summary" tabindex="-1">get_project_allocation_summary <a class="header-anchor" href="#get_project_allocation_summary" aria-label="Permalink to &quot;get_project_allocation_summary {#get_project_allocation_summary}&quot;">​</a></h2><p>All envelopes for one project, bucketed by <code>(user_id, project_id, task_id)</code>.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>03. Users</code>, <code>01. Time Entries</code>, <code>05. Tasks</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code></p><p>Multiple envelopes for the same person+task collapse into one row (see bucket model above). <code>hours_logged</code> is attributed once per entry — no double-counting when a person has two envelopes on the same task.</p><hr><h2 id="get_team_availability" tabindex="-1">get_team_availability <a class="header-anchor" href="#get_team_availability" aria-label="Permalink to &quot;get_team_availability {#get_team_availability}&quot;">​</a></h2><p>Remaining hours per person across all active envelopes.</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>01. Time Entries</code>, <code>03. Users</code></p><p><strong>Returns per person</strong>: available_hours, allocated_hours, remaining_hours, overbooked flag</p><p>Use this for a quick capacity snapshot before adding new work.</p><hr><h2 id="get_estimates_vs_actuals" tabindex="-1">get_estimates_vs_actuals <a class="header-anchor" href="#get_estimates_vs_actuals" aria-label="Permalink to &quot;get_estimates_vs_actuals {#get_estimates_vs_actuals}&quot;">​</a></h2><p>Compare allocated hours (the plan) against logged hours (the actuals).</p><p><strong>Reads from</strong>: <code>07. Budgets</code>, <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>week_start</code></td><td><code>&quot;this week&quot;</code>, <code>&quot;last week&quot;</code>, or <code>YYYY-MM-DD</code></td></tr><tr><td><code>user_name</code></td><td>Optional — filter to one person</td></tr><tr><td><code>project_name</code></td><td>Optional — filter to one project</td></tr></tbody></table><p><strong>Returns</strong>: per person/project: allocated_hours, actual_hours, delta</p><ul><li><code>delta &gt; 0</code> = over plan (more hours worked than allocated)</li><li><code>delta &lt; 0</code> = under plan (fewer hours than allocated)</li></ul><p>Surface meaningful divergences (delta ≥ ±20%) as insights. Never show estimates vs actuals for future weeks — redirect to <code>get_allocations</code> instead.</p><hr><h2 id="check_capacity" tabindex="-1">check_capacity <a class="header-anchor" href="#check_capacity" aria-label="Permalink to &quot;check_capacity {#check_capacity}&quot;">​</a></h2><p>Can the team absorb new work? Takes discipline requirements and a timeline.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>discipline_requirements</code></td><td>Array of <code>{discipline, hours_needed}</code></td></tr><tr><td><code>start_date</code></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>end_date</code></td><td><code>YYYY-MM-DD</code></td></tr></tbody></table><p><strong>Returns per discipline:</strong></p><ul><li><code>fte_sufficient</code>: FTE has headroom — names and available hours</li><li><code>fte_partial</code>: FTE bench partially covers — gap amount</li><li><code>contractor_required</code>: No FTE capacity — hours of contractor coverage needed</li><li>Contractor conflicts flagged if any contractors are double-booked</li></ul><hr><h2 id="get_capacity_forecast" tabindex="-1">get_capacity_forecast <a class="header-anchor" href="#get_capacity_forecast" aria-label="Permalink to &quot;get_capacity_forecast {#get_capacity_forecast}&quot;">​</a></h2><p>N-week rolling capacity outlook.</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td></td></tr><tr><td><code>weeks</code></td><td>Number of weeks to forecast (default 4, max 12)</td></tr></tbody></table><p><strong>Returns per week:</strong></p><ul><li>week_start, utilization_percent, unallocated_hours</li><li>uncovered_projects: projects with no one allocated that week</li><li>overbooked users: name + hours over</li></ul><p><strong>Interpretation:</strong></p><ul><li>&lt; 70% utilization → plenty of headroom</li><li>70–90% → healthy</li><li><blockquote><p>90% → nearly full, be careful</p></blockquote></li><li>uncovered_projects → flag immediately — no coverage that week</li></ul>',114)])])}const g=t(d,[["render",s]]);export{u as __pageData,g as default};
